<?php declare(strict_types=1);use FastWebsite\Core\View;?>
<section class="admin-page-heading"><div><p class="eyebrow">Reusable assets</p><h1>Media library</h1><p>Upload once, store the URL, and reuse the image throughout the website.</p></div></section><?php if(($errors??[])!==[]):?><div class="form-alert"><ul><?php foreach($errors as$e):?><li><?=View::escape($e)?></li><?php endforeach;?></ul></div><?php endif;?><section class="admin-card"><h2>Upload image</h2><form class="content-form" enctype="multipart/form-data" method="post" action="<?=View::escape($baseUrl)?>admin/media"><input type="hidden" name="_token" value="<?=View::escape($csrfToken)?>"><div class="form-grid"><div class="form-field"><label>Image *</label><input type="file" name="image" accept="image/jpeg,image/png,image/webp,image/gif" required></div><div class="form-field"><label>Accessible description *</label><input name="alt_text" required maxlength="255"></div></div><button class="button button-primary">Upload image</button></form></section><section class="admin-card"><div class="table-wrap"><table><thead><tr><th>Image</th><th>Stored URL</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php if($items===[]):?><tr><td colspan="4">No images yet.</td></tr><?php endif;?><?php foreach($items as$i):?><tr><td><strong><?=View::escape($i['original_name'])?></strong><br><small><?=number_format((int)$i['file_size']/1024)?> KB</small></td><td><code><?=View::escape($baseUrl.ltrim(str_replace('public/','',$i['file_path']),'/'))?></code></td><td><?=View::escape($i['status'])?></td><td><div class="table-actions"><a href="<?=View::escape($baseUrl)?>admin/media/<?=(int)$i['id']?>/edit">Edit</a><?php $a=$i['status']==='active'?'archive':'restore';?><form method="post" action="<?=View::escape($baseUrl)?>admin/media/<?=(int)$i['id']?>/workflow"><input type="hidden" name="_token" value="<?=View::escape($csrfToken)?>"><button class="link-button" name="action" value="<?=$a?>"><?=ucfirst($a)?></button></form></div></td></tr><?php endforeach;?></tbody></table></div></section>
